     1|/*
     2| * IVX Reels — enterprise full-screen vertical video experience for ivxholding.com.
     3| *
     4| * Instagram-grade behaviors on top of the IVX video platform API:
     5| *   full-screen snap feed · infinite scroll · autoplay/pause · adaptive HLS
     6| *   double-tap like · comments · share · save · follow · stories · live row
     7| *   audience channels (Investor / Buyer / Realtor / Builder / JV Deals)
     8| *   personalized ranking (viewer id + zip + watch history) · analytics beacons
     9| *   upload with progress (mobile + desktop) · creator dashboard · report
    10| */
    11|(function () {
    12|  'use strict';
    13|  if (window.__ivxReelsLoaded) return;
    14|  window.__ivxReelsLoaded = true;
    15|
    16|  /* ---------- config ---------- */
    17|  /*
    18|   * API resolution — the static landing host (ivxholding.com on S3) answers every
    19|   * /api/* path with index.html, which is NOT an API. We must always talk to the
    20|   * real backend. Preference order:
    21|   *   1. meta[ivx-backend-url]   (real backend, e.g. https://api.ivxholding.com)
    22|   *   2. meta[ivx-api-url]       (only if it is not the static site itself)
    23|   *   3. https://api.ivxholding.com
    24|   * Plus runtime failover: if a feed response is not JSON (static-site HTML) or
    25|   * the request fails, the next candidate host is promoted automatically.
    26|   */
    27|  var PROD_API = 'https://api.ivxholding.com';
    28|  var RENDER_API = 'https://ivx-holdings-platform.onrender.com';
    29|  function readMeta(name) {
    30|    var m = document.querySelector('meta[name="' + name + '"]');
    31|    var v = (m && m.getAttribute('content')) || '';
    32|    v = v.trim().replace(/\/+$/, '');
    33|    if (!v || v.indexOf('__IVX') === 0) return '';
    34|    return v;
    35|  }
    36|  function isStaticSiteHost(url) {
    37|    try {
    38|      var h = new URL(url).host.toLowerCase();
    39|      if (h === 'ivxholding.com' || h === 'www.ivxholding.com') return true;
    40|      if (location.host && h === location.host.toLowerCase()) return true;
    41|      return false;
    42|    } catch (e) { return true; }
    43|  }
    44|  var API = readMeta('ivx-backend-url') || readMeta('ivx-api-url') || PROD_API;
    45|  if (isStaticSiteHost(API)) API = PROD_API;
    46|  var API_CANDIDATES = [API, PROD_API, RENDER_API].filter(function (v, i, a) { return v && a.indexOf(v) === i; });
    47|
    48|  var HLS_CDN = 'https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js';
    49|  /*
    50|   * Channels — '' is the CANONICAL unified feed (identical order on landing,
    51|   * Android, iOS, Expo): 3 investor deal videos → 1 Featured Investor Video →
    52|   * repeat. '__reels' is the Project Reels rail (?type=reel) — construction
    53|   * updates never interrupt the investor deal flow.
    54|   */
    55|  var CHANNELS = [
    56|    { id: '', label: 'Deals' },
    57|    { id: '__reels', label: 'Project Reels' },
    58|    { id: 'investor', label: 'Investor' },
    59|    { id: 'buyer', label: 'Buyer' },
    60|    { id: 'realtor', label: 'Realtor' },
    61|    { id: 'builder', label: 'Builder' },
    62|    { id: 'jv', label: 'JV Deals' }
    63|  ];
    64|
    65|  function viewerId() {
    66|    try {
    67|      var id = localStorage.getItem('ivx_viewer_id');
    68|      if (!id) {
    69|        id = 'guest-' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
    70|        localStorage.setItem('ivx_viewer_id', id);
    71|      }
    72|      return id;
    73|    } catch (e) { return 'guest-anon'; }
    74|  }
    75|  var VIEWER = viewerId();
    76|
    77|  /* ---------- analytics beacon queue ---------- */
    78|  var eventQueue = [];
    79|  function track(ev) {
    80|    ev.viewer_id = VIEWER;
    81|    eventQueue.push(ev);
    82|    if (eventQueue.length >= 10) flushEvents(false);
    83|    /* Bridge to ad platform + first-party analytics */
    84|    try {
    85|      var evType = ev.type || '';
    86|      var vidId = ev.video_id || '';
    87|      if (typeof ivxTrack === 'function') {
    88|        var trackMap = {
    89|          'view': 'reel_view',
    90|          'complete': 'reel_complete',
    91|          'share': 'reel_share'
    92|        };
    93|        if (trackMap[evType]) ivxTrack(trackMap[evType], { video_id: vidId, watch_ms: ev.watch_ms || null });
    94|      }
    95|      if (typeof fireAdEvent === 'function') {
    96|        if (evType === 'view') fireAdEvent('view_content', { content_name: 'reel', property_id: vidId, category: 'reel' });
    97|        if (evType === 'complete') fireAdEvent('view_content', { content_name: 'reel_complete', property_id: vidId, category: 'reel_engagement' });
    98|      }
    99|    } catch(e) {}
   100|  }
   101|  function flushEvents(useBeacon) {
   102|    if (eventQueue.length === 0) return;
   103|    var payload = JSON.stringify({ events: eventQueue.splice(0, eventQueue.length) });
   104|    var url = API + '/api/ivx/video-platform/events';
   105|    if (useBeacon && navigator.sendBeacon) {
   106|      navigator.sendBeacon(url, new Blob([payload], { type: 'application/json' }));
   107|    } else {
   108|      fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: payload }).catch(function () {});
   109|    }
   110|  }
   111|  setInterval(function () { flushEvents(false); }, 5000);
   112|  document.addEventListener('visibilitychange', function () {
   113|    if (document.hidden) {
   114|      flushEvents(true);
   115|      deactivateCurrent();
   116|    }
   117|  });
   118|  window.addEventListener('pagehide', function () { flushEvents(true); });
   119|
   120|  /* ---------- HLS ---------- */
   121|  var hlsLoading = null;
   122|  function loadHlsJs() {
   123|    if (window.Hls) return Promise.resolve();
   124|    if (hlsLoading) return hlsLoading;
   125|    hlsLoading = new Promise(function (resolve) {
   126|      var s = document.createElement('script');
   127|      s.src = HLS_CDN; s.async = true;
   128|      s.onload = function () { resolve(); };
   129|      s.onerror = function () { resolve(); };
   130|      document.head.appendChild(s);
   131|    });
   132|    return hlsLoading;
   133|  }
   134|  function attachSource(video, hlsUrl, fallbackUrl) {
   135|    if (video.__ivxAttached) return;
   136|    video.__ivxAttached = true;
   137|    if (!hlsUrl) { if (fallbackUrl) video.src = fallbackUrl; return; }
   138|    if (video.canPlayType('application/vnd.apple.mpegurl')) { video.src = hlsUrl; return; }
   139|    loadHlsJs().then(function () {
   140|      if (window.Hls && window.Hls.isSupported()) {
   141|        var h = new window.Hls({ capLevelToPlayerSize: true, autoStartLoad: true, maxBufferLength: 15 });
   142|        h.on(window.Hls.Events.ERROR, function (_e, data) {
   143|          if (data && data.fatal) { try { h.destroy(); } catch (e) {} if (fallbackUrl) video.src = fallbackUrl; }
   144|        });
   145|        h.loadSource(hlsUrl);
   146|        h.attachMedia(video);
   147|        video.__ivxHls = h;
   148|      } else if (fallbackUrl) {
   149|        video.src = fallbackUrl;
   150|      }
   151|    });
   152|  }
   153|
   154|  /* ---------- styles ---------- */
   155|  var css = ''
   156|    + '#ivxReelsBtn{position:fixed;left:16px;bottom:18px;z-index:99990;display:flex;align-items:center;gap:8px;'
   157|    + 'background:linear-gradient(135deg,#E6C200,#E6C200);color:#fff;border:none;border-radius:999px;padding:12px 20px;'
   158|    + 'font:600 15px/1 -apple-system,Segoe UI,sans-serif;box-shadow:0 6px 24px rgba(0,0,0,.35);cursor:pointer;transition:transform .15s}'
   159|    + '#ivxReelsBtn:active{transform:scale(.94)}'
