   163|    + 'background:linear-gradient(rgba(0,0,0,.65),transparent);display:flex;flex-direction:column;gap:8px}'
   164|    + '.ivxr-row{display:flex;align-items:center;gap:8px}'
   165|    + '.ivxr-tabs{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;flex:1}'
   166|    + '.ivxr-tabs::-webkit-scrollbar{display:none}'
   167|    + '.ivxr-tab{flex:0 0 auto;background:rgba(255,255,255,.14);color:#fff;border:none;border-radius:999px;padding:7px 14px;'
   168|    + 'font:600 13px/1 -apple-system,Segoe UI,sans-serif;cursor:pointer}'
   169|    + '.ivxr-tab.on{background:#fff;color:#000}'
   170|    + '.ivxr-ico{background:rgba(255,255,255,.14);color:#fff;border:none;border-radius:50%;width:38px;height:38px;'
   171|    + 'font-size:19px;line-height:1;cursor:pointer;flex:0 0 auto;display:flex;align-items:center;justify-content:center}'
   172|    + '.ivxr-stories{display:flex;gap:10px;overflow-x:auto;scrollbar-width:none;padding:2px 2px 4px}'
