   310|    b.className = 'ivxr-tab' + (ch.id === '' ? ' on' : '');
   311|    b.textContent = ch.label;
   312|    b.addEventListener('click', function () {
   313|      if (state.channel === ch.id) return;
   314|      state.channel = ch.id;
   315|      tabsEl.querySelectorAll('.ivxr-tab').forEach(function (x) { x.classList.remove('on'); });
   316|      b.classList.add('on');
