   323|  /* ---------- feed loading ---------- */
   324|  function resetFeed() {
   325|    deactivateCurrent();
   326|    feedEl.innerHTML = '';
   327|    state.cursor = null;
   328|    state.done = false;
   329|    state.videos = {};
   330|    state.storyMode = false;
   331|  }
   332|
   333|  function feedPath() {
   334|    var u = '/api/ivx/video-platform/feed?limit=6&viewer_id=' + encodeURIComponent(VIEWER);
   335|    if (state.channel === '__reels') u += '&type=reel';
   336|    else if (state.channel) u += '&channel=' + encodeURIComponent(state.channel);
   337|    if (state.cursor) u += '&cursor=' + encodeURIComponent(state.cursor);
   338|    return u;
   339|  }
   340|
   341|  /**
   342|   * Fetch a JSON API path with host failover. The static S3 site returns
   343|   * index.html (text/html) for unknown paths — that is treated as a miss and the
   344|   * next candidate host is tried. The first host that answers valid JSON is
   345|   * promoted to `API` so all subsequent calls (likes, comments, upload, events)
   346|   * use the working backend.
   347|   */
   348|  function apiFetchJson(path, hostIdx) {
   349|    hostIdx = hostIdx || 0;
   350|    if (hostIdx >= API_CANDIDATES.length) return Promise.reject(new Error('all API hosts failed'));
   351|    var base = API_CANDIDATES[hostIdx];
   352|    return fetch(base + path)
   353|      .then(function (r) {
   354|        var ct = (r.headers.get('content-type') || '').toLowerCase();
   355|        if (!r.ok || ct.indexOf('json') === -1) throw new Error('bad response ' + r.status + ' ' + ct);
   356|        return r.json().then(function (data) {
   357|          if (API !== base) API = base; /* promote working host */
   358|          return data;
   359|        });
   360|      })
   361|      .catch(function () { return apiFetchJson(path, hostIdx + 1); });
