   624|  const deal = video.deal ?? null;
   625|  const mediaType: ReelMediaType = video.video_url ? 'video' : 'image';
   626|  const minOwnership = deal?.price && deal?.min_investment
   627|    ? `${((deal.min_investment / deal.price) * 100).toFixed(4)}%`
   628|    : null;
