   630|  // Parse title: "Property Name — Tour Label" or "Property Name — City, State"
   631|  const rawTitle = video.title ?? deal?.title ?? 'IVX Holdings';
   632|  const locationMatch = rawTitle.match(/(.+?)\s*[—–]\s*([^,]+,\s*[A-Z]{2})/);
   633|  let title = rawTitle;
   634|  let subtitle = 'Property Tour';
   635|  let location: string | null = null;
   636|
   637|  if (locationMatch) {
   638|    title = locationMatch[1].trim();
   639|    location = locationMatch[2].trim();
   640|  } else {
   641|    const tourMatch = rawTitle.match(/(.+?)\s*[—–]\s*(.+)/);
   642|    if (tourMatch) {
   643|      title = tourMatch[1].trim();
   644|      const tour = tourMatch[2].trim();
   645|      const isLocation = /,\s*[A-Z]{2}/.test(tour);
   646|      location = isLocation ? tour : null;
   647|      subtitle = isLocation ? 'Property Tour' : tour;
   648|    }
   649|  }
