   651|  return {
   652|    reelId: video.id,
   653|    dealId: deal?.id ?? null,
   654|    propertyId: video.property_id ?? video.project_id ?? null,
   655|    investmentId: deal?.id ?? null,
   656|    slug: null,
   657|    title: deal?.title ?? title,
   658|    subtitle,
