   662|    hlsUrl: video.hls_url,
   663|    posterUrl: video.poster_url ?? video.thumbnail_url,
   664|    previewBlurUrl: video.preview_blur_url,
   665|    roi: deal?.expected_roi ? parseFloat(deal.expected_roi) : null,
   666|    minimumInvestment: deal?.min_investment ?? null,
